def action(code):
    if 200 <= code < 300:
        return "ok"
    if code in (301, 302):
        return "redirect"
    if code == 404:
        return "not_found"
    if 400 <= code < 500:
        return "client_error"
    if 500 <= code < 600:
        return "retry"
    return "unknown"

